?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QRIS Generator</title>
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js"></script>
<style>
*{box-sizing:border-box}body{margin:0;background:#eee;font-family:Arial}.top{background:#fff;padding:14px;position:sticky;top:0;z-index:5;box-shadow:0 2px 10px #0002}.topin{max-width:1100px;margin:auto;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.badge{background:#dcfce7;color:#166534;padding:8px;border-radius:20px}.logout{background:#111;color:#fff;padding:8px;border-radius:7px;text-decoration:none}.panel{max-width:1100px;margin:15px auto;padding:0 15px}.form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}input,textarea{width:100%;padding:12px;border:1px solid #ccc;border-radius:8px}textarea{grid-column:1/-1;min-height:90px}.upload{display:block;text-align:center;background:#fff;border:2px dashed #aaa;padding:16px;margin-top:10px;border-radius:10px}.upload span{display:block;color:#666;font-size:13px;margin-top:4px}#file{display:none}.buttons{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}button{padding:11px 16px;border:0;border-radius:8px;background:#111;color:#fff;font-weight:700}.green{background:#008f45}.blue{background:#1267d6}.red{background:#d71920}#status{display:none;padding:10px;margin-top:10px;border-radius:7px;font-size:13px}.success{display:block!important;background:#dcfce7;color:#166534}.error{display:block!important;background:#fee2e2;color:#991b1b}.loading{display:block!important;background:#dbeafe;color:#1e40af}.preview{padding:25px 10px 45px}#capture{width:100%;max-width:1080px;aspect-ratio:1080/1525;margin:auto;background:#fff;position:relative;overflow:hidden;box-shadow:0 5px 25px #0002}.r1{position:absolute;left:-10%;top:24%;width:30%;height:38%;background:#ed1c2e;clip-path:polygon(0 0,100% 35%,100% 76%,0 100%)}.r2{position:absolute;right:-2%;bottom:-1%;width:44%;height:28%;background:#ed1c2e;clip-path:polygon(100% 0,100% 100%,0 100%)}.content{position:absolute;inset:0;padding:4.5% 6.5%;text-align:center}.header{display:flex;justify-content:space-between;align-items:center}.qris{display:flex;align-items:center}.qs{font-size:clamp(25px,5.4vw,58px);font-weight:900;letter-spacing:-5px}.qt{margin-left:12px;font-size:clamp(11px,2.3vw,25px);font-weight:bold;text-align:left;line-height:1.05}.gpn{font-size:clamp(25px,4.4vw,48px);font-weight:900;font-style:italic;color:#244b7b}.merchant{margin-top:3.2%;font-size:clamp(18px,3.7vw,40px);font-weight:900;line-height:1.1}.nmid,.branch{margin-top:2.3%;font-size:clamp(14px,2.7vw,30px)}.qr-area{width:60%;aspect-ratio:1;margin:2.2% auto 0;padding:1%;background:#fff}.qrcode{width:100%;height:100%;display:flex;align-items:center;justify-content:center}.qrcode img,.qrcode canvas{width:100%!important;height:100%!important}.footer{position:absolute;left:6.5%;right:6.5%;bottom:8%;text-align:center}.ft{font-size:clamp(14px,2.7vw,29px)}.fp{margin-top:1%;font-size:clamp(11px,2.2vw,24px)}.print{position:absolute;left:6.5%;bottom:2.3%;font-size:clamp(8px,1.75vw,19px)}.guide{position:absolute;right:2%;bottom:1.5%;color:#fff;text-align:center;font-size:clamp(7px,1.3vw,15px)}.items{display:flex;gap:10px}.item{width:clamp(30px,6vw,65px)}.ico{width:clamp(27px,5vw,55px);height:clamp(27px,5vw,55px);margin:auto;border:2px solid #111;border-radius:50%;background:#fff;color:#111;display:grid;place-items:center}@media(max-width:650px){.form{grid-template-columns:1fr}.buttons button{flex:1}}@media print{.top,.panel{display:none}.preview{padding:0}#capture{max-width:none;box-shadow:none}}
</style></head><body>
<div class="top"><div class="topin"><b>QRIS Generator — <?=e($c['name'])?></b><div><span class="badge">AKTIF sampai <?=e(date('d-m-Y',strtotime($c['subscription_expiry'])))?></span> <a class="logout" href="/logout.php">Keluar</a></div></div></div>
<div class="panel"><div class="form"><input id="merchant" value="<?=e($c['name'])?>"><input id="nmid" placeholder="NMID"><input id="branch" value="A01"><input id="printer" placeholder="Nomor cetak"><textarea id="payload" readonly placeholder="Payload otomatis setelah upload"></textarea></div>
<label class="upload" for="file">📷 <b>Upload Gambar QRIS Asli</b><span>Payload akan dibaca otomatis di browser</span></label><input id="file" type="file" accept="image/*"><div id="status"></div>
<div class="buttons"><button class="blue" onclick="gen()">Buat QR</button><button class="green" onclick="png()">Download PNG</button><button onclick="print()">Cetak</button><button class="red" onclick="clearAll()">Clear</button></div></div>
<div class="preview"><div id="capture"><div class="r1"></div><div class="r2"></div><div class="content"><div class="header"><div class="qris"><div class="qs">QRIS</div><div class="qt">QR Code Standar<br>Pembayaran Nasional</div></div><div class="gpn">GPN</div></div><div id="mt" class="merchant"><?=e($c['name'])?></div><div class="nmid">NMID : <span id="nm">-</span></div><div id="br" class="branch">A01</div><div class="qr-area"><div id="qr" class="qrcode">Upload QRIS</div></div><div class="footer"><div class="ft">SATU QRIS UNTUK SEMUA</div><div class="fp">Cek aplikasi penyelenggara<br>di: www.aspi-qris.id</div></div><div class="print">Dicetak Oleh : <span id="pr">-</span><br>Versi Cetak: 1.0</div></div><div class="guide">Cara bayar dengan QRIS:<div class="items"><div class="item"><div class="ico">▣</div></div><div class="item"><div class="ico">▤</div></div><div class="item"><div class="ico">✓</div></div></div></div></div></div>
<script>
const file=document.getElementById('file'),p=document.getElementById('payload'),cv=document.createElement('canvas'),cx=cv.getContext('2d',{willReadFrequently:true}),st=document.getElementById('status');
function S(t,c){st.className=c;st.textContent=t}
file.onchange=()=>{let f=file.files[0];if(!f)return;S('⏳ Membaca QR Code...','loading');let r=new FileReader();r.onload=()=>{let i=new Image();i.onload=()=>scan(i);i.src=r.result};r.readAsDataURL(f)};
function scan(i){let w=i.naturalWidth,h=i.naturalHeight,m=2200;if(w>m){let s=m/w;w*=s;h*=s}if(h>m){let s=m/h;w*=s;h*=s}w=Math.round(w);h=Math.round(h);cv.width=w;cv.height=h;cx.drawImage(i,0,0,w,h);let d=cx.getImageData(0,0,w,h),x=jsQR(d.data,w,h,{inversionAttempts:'attemptBoth'});if(!x){S('❌ QR Code tidak ditemukan.','error');return}p.value=x.data;S('✅ Payload berhasil diambil otomatis.','success');gen()}
function gen(){let x=p.value.trim();if(!x)return;document.getElementById('mt').textContent=document.getElementById('merchant').value;document.getElementById('nm').textContent=document.getElementById('nmid').value||'-';document.getElementById('br').textContent=document.getElementById('branch').value||'A01';document.getElementById('pr').textContent=document.getElementById('printer').value||'-';let q=document.getElementById('qr');q.innerHTML='';new QRCode(q,{text:x,width:626,height:626,correctLevel:QRCode.CorrectLevel.M})}
async function png(){if(!p.value.trim())return alert('Upload QRIS terlebih dahulu.');let c=await html2canvas(document.getElementById('capture'),{scale:2,backgroundColor:'#fff'}),a=document.createElement('a');a.download='qris-merchant.png';a.href=c.toDataURL();a.click()}
function clearAll(){file.value='';p.value='';st.className='';st.textContent='';document.getElementById('qr').textContent='Upload QRIS'}
</script></body></html>
